# Статья: переход со старой ERP (или Excel) на Odoo без хаоса – инвентаризация процессов и интерфейсов, какие данные
# переносить, пробные миграции на копии, big bang / по этапам / параллельная работа, план выходных переключения,
# сверки, критерии отката, первая неделя. Языки: en, de, ru, uk (fr/el – английская версия).

SWITCH_POST = {
    "slug": "switch-to-odoo-old-erp-cutover-plan-data-migration-parallel-run",
    "date": "2026-11-25",
    "tags": ["Odoo", "Migration", "ERP", "Implementation"],
    "code": {
        "check": ("python · compare counts and totals after the import (Odoo 17, XML-RPC)", """import xmlrpc.client

URL, DB, USER, KEY = "https://odoo.example.com", "prod", "admin@example.com", "API-KEY"   # API key, not the password
common = xmlrpc.client.ServerProxy(f"{URL}/xmlrpc/2/common")
uid = common.authenticate(DB, USER, KEY, {})
m = xmlrpc.client.ServerProxy(f"{URL}/xmlrpc/2/object")
call = lambda model, method, *a, **kw: m.execute_kw(DB, uid, KEY, model, method, list(a), kw)

# numbers from the old system (final export) – fill in before the check
expected = {"customers": 1840, "products": 5210, "open_receivables": 412_380.55, "open_payables": 188_904.10}

got = {
    "customers": call("res.partner", "search_count", [("customer_rank", ">", 0)]),
    "products": call("product.product", "search_count", [("active", "=", True)]),
}
open_items = call("account.move", "read_group",
                  [("state", "=", "posted"), ("payment_state", "in", ["not_paid", "partial"]),
                   ("move_type", "in", ["out_invoice", "out_refund", "in_invoice", "in_refund"])],
                  ["amount_residual_signed:sum"], ["move_type"], lazy=False)
by_type = {g["move_type"]: g["amount_residual_signed"] for g in open_items}
got["open_receivables"] = round(by_type.get("out_invoice", 0) + by_type.get("out_refund", 0), 2)
got["open_payables"] = round(-(by_type.get("in_invoice", 0) + by_type.get("in_refund", 0)), 2)

for k, v in expected.items():
    ok = abs(got[k] - v) < 0.01
    print(f"{k:18} expected {v:>14,}  odoo {got[k]:>14,}  {'OK' if ok else '<-- CHECK'}")"""),
    },
    "links": [
        ("Blog: what Odoo really costs in Germany", "@blog:odoo-costs-licence-hosting-implementation-germany"),
        ("Blog: test copy of the database without cron jobs", "@blog:odoo-stage-restore-stop-cron-jobs"),
        ("Blog: pg_dump / pg_restore for Odoo", "@blog:pg-dump-pg-restore-odoo-docker-systemd-remote"),
        ("Blog: DATEV export from Odoo", "@blog:odoo-datev-export-step-by-step-community-enterprise"),
        ("Odoo 17 external API (odoo.com)", "https://www.odoo.com/documentation/17.0/developer/reference/external_api.html"),
        ("Our hour packs", "@page:#packs"),
    ],
    "t": {},
}

